package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        Locale originalLocale = Locale.getDefault();
        TimeZone originalTimeZone = TimeZone.getDefault();

        String oracleId = null;
        String detail = null;

        try {
            TimeZone.setDefault(TimeZone.getTimeZone("UTC"));

            FastDateFormat format1;
            FastDateFormat format2;
            FastDateFormat format3;

            try {
                Locale.setDefault(Locale.US);
                format1 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
                format2 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
                Locale.setDefault(Locale.GERMANY);
                format3 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
            } catch (RuntimeException e) {
                return;
            }

            if (format1.getLocale() != Locale.GERMANY) {
                oracleId = "lifted-format1-locale";
                detail = "semantic mismatch: expected same locale de_DE for explicit-locale getDateTimeInstance(FULL,FULL,Locale.GERMANY), got " + format1.getLocale();
            } else if (format2.getLocale() != Locale.US) {
                oracleId = "lifted-format2-locale";
                detail = "semantic mismatch: expected same locale en_US for default-locale getDateTimeInstance(FULL,FULL) after Locale.setDefault(Locale.US), got " + format2.getLocale();
            } else if (format3.getLocale() != Locale.GERMANY) {
                oracleId = "lifted-format3-locale";
                detail = "semantic mismatch: expected same locale de_DE for default-locale getDateTimeInstance(FULL,FULL) after Locale.setDefault(Locale.GERMANY), got " + format3.getLocale();
            } else if (format1 == format2) {
                oracleId = "lifted-format1-ne-format2";
                detail = "semantic mismatch: expected distinct formatter instances for explicit Germany vs default US";
            } else if (format2 == format3) {
                oracleId = "lifted-format2-ne-format3";
                detail = "semantic mismatch: expected distinct formatter instances across changed default locales";
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            Date fixed = new Date(1042212800000L);
            String usRendered;
            String deRendered;
            String explicitUsRendered;
            String explicitDeRendered;
            try {
                explicitUsRendered = normalize(FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.US).format(fixed));
                explicitDeRendered = normalize(FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY).format(fixed));
                usRendered = normalize(format2.format(fixed));
                deRendered = normalize(format3.format(fixed));
            } catch (RuntimeException e) {
                return;
            }

            /* Contract justification:
             * getDateTimeInstance(dateStyle,timeStyle) is documented to use the default locale in force at the time of the call.
             * Therefore, after setting the default locale to US/GERMANY, the no-locale overload must behave the same as the explicit-locale overload on the same input.
             * This post-condition catches a band-aid that only fixes getLocale() but still returns a stale cached formatter. */
            if (!usRendered.equals(explicitUsRendered)) {
                oracleId = "datetime-render-us-equivalence";
                detail = "semantic mismatch: default-locale US formatter rendered " + usRendered + " but explicit US rendered " + explicitUsRendered;
            } else if (!deRendered.equals(explicitDeRendered)) {
                oracleId = "datetime-render-de-equivalence";
                detail = "semantic mismatch: default-locale Germany formatter rendered " + deRendered + " but explicit Germany rendered " + explicitDeRendered;
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            int[] styles = new int[] {
                FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
            };
            int dateStyle = styles[data.consumeInt(0, 3)];
            int timeStyle = styles[data.consumeInt(0, 3)];

            FastDateFormat a;
            FastDateFormat b;
            Locale la;
            Locale lb;
            try {
                Locale.setDefault(Locale.US);
                a = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                la = a.getLocale();
                Locale.setDefault(Locale.GERMANY);
                b = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                lb = b.getLocale();
            } catch (RuntimeException e) {
                return;
            }

            /* Contract justification:
             * the no-locale overload is documented to use the default locale; thus the returned formatter's locale must equal the current default locale at each call site. */
            if (la != Locale.US || lb != Locale.GERMANY) {
                oracleId = "datetime-default-locale-relation";
                detail = "semantic mismatch: expected locales en_US and de_DE, got " + la + " and " + lb;
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            String pattern = "EEEE, dd MMMM yyyy HH:mm:ss z";
            FastDateFormat giUs;
            FastDateFormat giDe;
            Locale giUsLocale;
            Locale giDeLocale;
            String giUsRendered;
            String giDeRendered;
            try {
                Locale.setDefault(Locale.US);
                giUs = FastDateFormat.getInstance(pattern);
                giUsLocale = giUs.getLocale();
                giUsRendered = normalize(giUs.format(fixed));

                Locale.setDefault(Locale.GERMANY);
                giDe = FastDateFormat.getInstance(pattern);
                giDeLocale = giDe.getLocale();
                giDeRendered = normalize(giDe.format(fixed));
            } catch (RuntimeException e) {
                return;
            }

            /* Independent oracle outside the lifted families:
             * getInstance(String pattern) is a getter/factory that uses the current default locale when no locale is supplied.
             * Two calls made under different default locales must therefore capture different locales, and a locale-sensitive pattern with textual fields must render differently.
             * This reaches the shared getInstance path directly and would still fail if a patch only special-cased the reported getDateTimeInstance symptom. */
            if (giUsLocale != Locale.US || giDeLocale != Locale.GERMANY) {
                oracleId = "getinstance-default-locale-capture";
                detail = "semantic mismatch: expected getInstance(pattern) to capture en_US then de_DE, got " + giUsLocale + " and " + giDeLocale;
            } else if (giUs == giDe) {
                oracleId = "getinstance-distinct-instances";
                detail = "semantic mismatch: expected distinct getInstance(pattern) results across different default locales";
            } else if (giUsRendered.equals(giDeRendered)) {
                oracleId = "getinstance-render-diff";
                detail = "semantic mismatch: expected locale-sensitive rendering to differ for US vs Germany, got " + giUsRendered;
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            Locale beforeLocale = Locale.getDefault();
            TimeZone beforeTimeZone = TimeZone.getDefault();
            try {
                FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                FastDateFormat.getInstance(pattern);
            } catch (RuntimeException e) {
                return;
            }
            Locale afterLocale = Locale.getDefault();
            TimeZone afterTimeZone = TimeZone.getDefault();

            /* Hidden-state check:
             * get* factory methods are query/factory operations; nothing in their contract says they mutate JVM-wide defaults.
             * A cover-up patch that changes global Locale/TimeZone to fake a result would violate this observable post-condition. */
            if (beforeLocale != afterLocale || !beforeTimeZone.equals(afterTimeZone)) {
                oracleId = "global-defaults-unchanged";
                detail = "semantic mismatch: factory call mutated defaults from locale=" + beforeLocale + ", tz=" + beforeTimeZone.getID() + " to locale=" + afterLocale + ", tz=" + afterTimeZone.getID();
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }
        } finally {
            Locale.setDefault(originalLocale);
            TimeZone.setDefault(originalTimeZone);
        }
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static void throwAfterRestore(Locale locale, TimeZone timeZone, String oracleId, String detail) {
        Locale.setDefault(locale);
        TimeZone.setDefault(timeZone);
        throw new FuzzerSecurityIssueLow("[oracle:" + oracleId + "] " + detail);
    }
}

