        Locale originalLocale = Locale.getDefault();
        TimeZone originalTimeZone = TimeZone.getDefault();

        String oracleId = null;
        String detail = null;

        try {
            TimeZone utc = TimeZone.getTimeZone("UTC");
            TimeZone.setDefault(utc);
            Date fixed = new Date(1042212800000L);

            String localeSensitivePattern = "MMMM";
            FastDateFormat giUs;
            FastDateFormat giDe;
            Locale giUsLocale;
            Locale giDeLocale;
            String giUsRendered;
            String giDeRendered;
            String expectedGiUsRendered;
            String expectedGiDeRendered;
            try {
                Locale.setDefault(Locale.US);
                giUs = FastDateFormat.getInstance(localeSensitivePattern);
                giUsLocale = giUs.getLocale();
                giUsRendered = normalize(giUs.format(fixed));

                Locale.setDefault(Locale.GERMANY);
                giDe = FastDateFormat.getInstance(localeSensitivePattern);
                giDeLocale = giDe.getLocale();
                giDeRendered = normalize(giDe.format(fixed));

                SimpleDateFormat expectedUs = new SimpleDateFormat(localeSensitivePattern, Locale.US);
                expectedUs.setTimeZone(utc);
                expectedGiUsRendered = normalize(expectedUs.format(fixed));

                SimpleDateFormat expectedDe = new SimpleDateFormat(localeSensitivePattern, Locale.GERMANY);
                expectedDe.setTimeZone(utc);
                expectedGiDeRendered = normalize(expectedDe.format(fixed));
            } catch (RuntimeException e) {
                return;
            }

            /* Contract justification:
             * getInstance(String pattern) is the no-locale overload of the formatter factory; like the sibling no-locale factories,
             * it must capture the default locale in force at the time of the call. This probes the shared getInstance path directly,
             * not just getDateTimeInstance. */
            if (giUsLocale != Locale.US) {
                oracleId = "getinstance-default-locale-us";
                detail = "semantic mismatch: expected getInstance(\"MMMM\") under Locale.US to capture en_US, got " + giUsLocale;
            } else if (giDeLocale != Locale.GERMANY) {
                oracleId = "getinstance-default-locale-de";
                detail = "semantic mismatch: expected getInstance(\"MMMM\") under Locale.GERMANY to capture de_DE, got " + giDeLocale;
            } else if (giUs == giDe) {
                oracleId = "getinstance-distinct-cache-entries";
                detail = "semantic mismatch: expected distinct getInstance(\"MMMM\") results across changed default locales";
            } else if (!giUsRendered.equals(expectedGiUsRendered)) {
                oracleId = "getinstance-jdk-render-us";
                detail = "semantic mismatch: FastDateFormat getInstance(\"MMMM\") under Locale.US rendered " + giUsRendered + " but JDK SimpleDateFormat rendered " + expectedGiUsRendered;
            } else if (!giDeRendered.equals(expectedGiDeRendered)) {
                oracleId = "getinstance-jdk-render-de";
                detail = "semantic mismatch: FastDateFormat getInstance(\"MMMM\") under Locale.GERMANY rendered " + giDeRendered + " but JDK SimpleDateFormat rendered " + expectedGiDeRendered;
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            int[] styles = new int[] {
                FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
            };
            int dateStyle = styles[data.consumeInt(0, 3)];
            int timeStyle = styles[data.consumeInt(0, 3)];

            FastDateFormat dtUs;
            FastDateFormat dtDe;
            String dtUsPattern;
            String dtDePattern;
            String expectedDtUsPattern;
            String expectedDtDePattern;
            try {
                Locale.setDefault(Locale.US);
                dtUs = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                dtUsPattern = dtUs.getPattern();

                Locale.setDefault(Locale.GERMANY);
                dtDe = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                dtDePattern = dtDe.getPattern();

                expectedDtUsPattern = ((SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US)).toPattern();
                expectedDtDePattern = ((SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.GERMANY)).toPattern();
            } catch (RuntimeException e) {
                return;
            }

            /* Contract justification:
             * getDateTimeInstance(dateStyle,timeStyle) obtains a formatter using the specified styles in the default locale.
             * Its observable pattern must therefore match the JDK DateFormat pattern for that locale and style pair. This is a
             * different observable axis from locale identity or rendered output equality. */
            if (!dtUsPattern.equals(expectedDtUsPattern)) {
                oracleId = "datetime-default-pattern-us";
                detail = "semantic mismatch: expected default-locale US pattern " + expectedDtUsPattern + " but got " + dtUsPattern;
            } else if (!dtDePattern.equals(expectedDtDePattern)) {
                oracleId = "datetime-default-pattern-de";
                detail = "semantic mismatch: expected default-locale Germany pattern " + expectedDtDePattern + " but got " + dtDePattern;
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            int dateOnlyStyle = styles[data.consumeInt(0, 3)];
            FastDateFormat dUs;
            FastDateFormat dDe;
            String dUsPattern;
            String dDePattern;
            String expectedDUsPattern;
            String expectedDDePattern;
            try {
                Locale.setDefault(Locale.US);
                dUs = FastDateFormat.getDateInstance(dateOnlyStyle);
                dUsPattern = dUs.getPattern();

                Locale.setDefault(Locale.GERMANY);
                dDe = FastDateFormat.getDateInstance(dateOnlyStyle);
                dDePattern = dDe.getPattern();

                expectedDUsPattern = ((SimpleDateFormat) DateFormat.getDateInstance(dateOnlyStyle, Locale.US)).toPattern();
                expectedDDePattern = ((SimpleDateFormat) DateFormat.getDateInstance(dateOnlyStyle, Locale.GERMANY)).toPattern();
            } catch (RuntimeException e) {
                return;
            }

            /* Contract justification:
             * getDateInstance(style) must use the default locale at the time of the call; thus its pattern must match the JDK
             * locale-specific date pattern for the same style. This reaches the other patched factory through real code. */
            if (!dUsPattern.equals(expectedDUsPattern)) {
                oracleId = "date-default-pattern-us";
                detail = "semantic mismatch: expected default-locale US date pattern " + expectedDUsPattern + " but got " + dUsPattern;
            } else if (!dDePattern.equals(expectedDDePattern)) {
                oracleId = "date-default-pattern-de";
                detail = "semantic mismatch: expected default-locale Germany date pattern " + expectedDDePattern + " but got " + dDePattern;
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            FastDateFormat format1;
            FastDateFormat format2;
            FastDateFormat format3;
            try {
                Locale.setDefault(Locale.US);
                format1 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
                format2 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
                Locale.setDefault(Locale.GERMANY);
                format3 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
            } catch (RuntimeException e) {
                return;
            }

            if (format1.getLocale() != Locale.GERMANY) {
                oracleId = "lifted-format1-locale";
                detail = "semantic mismatch: expected same locale de_DE for explicit-locale getDateTimeInstance(FULL,FULL,Locale.GERMANY), got " + format1.getLocale();
            } else if (format2.getLocale() != Locale.US) {
                oracleId = "lifted-format2-locale";
                detail = "semantic mismatch: expected same locale en_US for default-locale getDateTimeInstance(FULL,FULL) after Locale.setDefault(Locale.US), got " + format2.getLocale();
            } else if (format3.getLocale() != Locale.GERMANY) {
                oracleId = "lifted-format3-locale";
                detail = "semantic mismatch: expected same locale de_DE for default-locale getDateTimeInstance(FULL,FULL) after Locale.setDefault(Locale.GERMANY), got " + format3.getLocale();
            } else if (format1 == format2) {
                oracleId = "lifted-format1-ne-format2";
                detail = "semantic mismatch: expected distinct formatter instances for explicit Germany vs default US";
            } else if (format2 == format3) {
                oracleId = "lifted-format2-ne-format3";
                detail = "semantic mismatch: expected distinct formatter instances across changed default locales";
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }

            Locale beforeLocale = Locale.getDefault();
            TimeZone beforeTimeZone = TimeZone.getDefault();
            try {
                FastDateFormat.getInstance(localeSensitivePattern);
                FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                FastDateFormat.getDateInstance(dateOnlyStyle);
            } catch (RuntimeException e) {
                return;
            }
            Locale afterLocale = Locale.getDefault();
            TimeZone afterTimeZone = TimeZone.getDefault();

            /* Hidden-state check:
             * get* factory methods are query/factory operations; nothing in their contract permits mutating JVM-wide defaults.
             * A patch that tampers with global Locale/TimeZone to fake correct answers would violate this receiver-state/global-state axis. */
            if (beforeLocale != afterLocale || !beforeTimeZone.equals(afterTimeZone)) {
                oracleId = "global-defaults-unchanged";
                detail = "semantic mismatch: factory call mutated defaults from locale=" + beforeLocale + ", tz=" + beforeTimeZone.getID() + " to locale=" + afterLocale + ", tz=" + afterTimeZone.getID();
            }

            if (oracleId != null) {
                throwAfterRestore(originalLocale, originalTimeZone, oracleId, detail);
            }
        } finally {
            Locale.setDefault(originalLocale);
            TimeZone.setDefault(originalTimeZone);
        }
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static void throwAfterRestore(Locale locale, TimeZone timeZone, String oracleId, String detail) {
        Locale.setDefault(locale);
        TimeZone.setDefault(timeZone);
        throw new FuzzerSecurityIssueLow("[oracle:" + oracleId + "] " + detail);
    }
}

