package org.jfree.chart.util;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.jfree.chart.axis.CategoryAxis;
import org.jfree.chart.axis.NumberAxis;
import org.jfree.chart.plot.CategoryPlot;

public class FuzzHarness {
    private static void fail(String id, String msg) {
        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: " + msg);
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        CategoryAxis domainAxis1 = new CategoryAxis("X1");
        NumberAxis rangeAxis1 = new NumberAxis("Y1");
        NumberAxis rangeAxis2 = new NumberAxis("Y2");
        CategoryPlot plot = new CategoryPlot(null, domainAxis1, rangeAxis1, null);

        int hashBefore0 = plot.hashCode();
        int actual0 = plot.getRangeAxisIndex(rangeAxis1);
        if (actual0 != 0) {
            fail("lifted-rangeAxis1", "plot.getRangeAxisIndex(rangeAxis1) expected=0 actual=" + actual0);
        }
        if (plot.hashCode() != hashBefore0) {
            fail("readonly-hash-0", "getRangeAxisIndex(rangeAxis1) changed plot hashCode from " + hashBefore0 + " to " + plot.hashCode());
        }

        int hashBefore1 = plot.hashCode();
        int actual1 = plot.getRangeAxisIndex(rangeAxis2);
        if (actual1 != -1) {
            fail("lifted-rangeAxis2-absent", "plot.getRangeAxisIndex(rangeAxis2) expected=-1 actual=" + actual1);
        }
        if (plot.hashCode() != hashBefore1) {
            fail("readonly-hash-1", "getRangeAxisIndex(rangeAxis2) changed plot hashCode from " + hashBefore1 + " to " + plot.hashCode());
        }

        plot.setRangeAxis(1, rangeAxis2);

        int hashBefore2 = plot.hashCode();
        int actual2 = plot.getRangeAxisIndex(rangeAxis2);
        if (actual2 != 1) {
            fail("lifted-rangeAxis2-present", "after plot.setRangeAxis(1, rangeAxis2), plot.getRangeAxisIndex(rangeAxis2) expected=1 actual=" + actual2);
        }
        if (plot.hashCode() != hashBefore2) {
            fail("readonly-hash-2", "getRangeAxisIndex(rangeAxis2) changed plot hashCode from " + hashBefore2 + " to " + plot.hashCode());
        }

        NumberAxis distinctButEqualLooking = new NumberAxis("Y2");
        int hashBefore3 = plot.hashCode();
        int actual3 = plot.getRangeAxisIndex(distinctButEqualLooking);
        if (actual3 != -1) {
            fail("lifted-distinct-instance", "plot.getRangeAxisIndex(new NumberAxis(\"Y2\")) expected=-1 actual=" + actual3);
        }
        if (plot.hashCode() != hashBefore3) {
            fail("readonly-hash-3", "getRangeAxisIndex(distinct axis) changed plot hashCode from " + hashBefore3 + " to " + plot.hashCode());
        }

        boolean pass = false;
        int hashBeforeNull = plot.hashCode();
        try {
            plot.getRangeAxisIndex(null);
        } catch (IllegalArgumentException e) {
            pass = true;
        }
        if (!pass) {
            fail("lifted-null-rejection", "plot.getRangeAxisIndex(null) did not throw IllegalArgumentException");
        }
        if (plot.hashCode() != hashBeforeNull) {
            fail("readonly-hash-null", "getRangeAxisIndex(null) changed plot hashCode from " + hashBeforeNull + " to " + plot.hashCode());
        }

        int slot = data.consumeInt(1, 4);
        String axisLabel = data.consumeAsciiString(16);
        if (axisLabel.length() == 0) {
            axisLabel = "F";
        }

        CategoryAxis domainAxisF = new CategoryAxis("DX");
        NumberAxis baseRangeAxis = new NumberAxis("RY0");
        CategoryPlot fuzzPlot = new CategoryPlot(null, domainAxisF, baseRangeAxis, null);
        NumberAxis insertedAxis = new NumberAxis(axisLabel);

        try {
            fuzzPlot.setRangeAxis(slot, insertedAxis);

            int beforeLookupHash = fuzzPlot.hashCode();
            int observedSlot = fuzzPlot.getRangeAxisIndex(insertedAxis);

            /*
             * Contract/oracle: setRangeAxis(index, axis) establishes the plot's range-axis mapping,
             * and getRangeAxisIndex(axis) reports the index for that exact axis object. This is the
             * same writer/reader shared-state relation exercised by the lifted test. A patch that
             * merely deletes the null-argument throw or otherwise breaks the underlying ObjectList
             * bookkeeping can silently return the wrong index while never throwing.
             */
            if (observedSlot != slot) {
                fail("writer-reader-slot", "after setRangeAxis(" + slot + ", axis), getRangeAxisIndex(axis) expected=" + slot + " actual=" + observedSlot);
            }

            if (fuzzPlot.hashCode() != beforeLookupHash) {
                fail("readonly-hash-fuzz", "getRangeAxisIndex(insertedAxis) changed plot hashCode from " + beforeLookupHash + " to " + fuzzPlot.hashCode());
            }

            NumberAxis neverInserted = new NumberAxis(axisLabel);
            int absentIndex = fuzzPlot.getRangeAxisIndex(neverInserted);
            if (absentIndex != -1) {
                fail("identity-not-equality", "distinct NumberAxis instance with same label expected index -1 actual=" + absentIndex);
            }
        } catch (RuntimeException e) {
            return;
        }
    }
}

