            slotB = (slotA + 1) % 4;
        }

        CategoryPlot fuzzPlot = new CategoryPlot(null, new CategoryAxis("DX"), new NumberAxis("R0"), null);
        NumberAxis axisA = new NumberAxis(labelA);
        NumberAxis axisB = new NumberAxis(labelB);

        try {
            fuzzPlot.setRangeAxis(slotA, axisA);
            fuzzPlot.setRangeAxis(slotB, axisB);
        } catch (RuntimeException e) {
            return;
        }

        try {
            int idxA = fuzzPlot.getRangeAxisIndex(axisA);
            int idxB = fuzzPlot.getRangeAxisIndex(axisB);

            /*
             * Writer/reader contract via the real public API:
             * setRangeAxis(index, axis) establishes which slot contains that exact axis object,
             * and getRangeAxisIndex(axis) reports the slot for that same object reference.
             * This is a different receiver-state axis from the accepted domain-axis checks.
             */
            if (idxA != slotA) {
                fail("rangeaxis-writer-reader-a", "after setRangeAxis(" + slotA + ", axisA), getRangeAxisIndex(axisA) expected=" + slotA + " actual=" + idxA);
            }
            if (idxB != slotB) {
                fail("rangeaxis-writer-reader-b", "after setRangeAxis(" + slotB + ", axisB), getRangeAxisIndex(axisB) expected=" + slotB + " actual=" + idxB);
            }

            /*
             * Distinct-instance/identity oracle:
             * getRangeAxisIndex searches for the stored axis object, not merely an equal-looking label.
             * A fresh NumberAxis with the same label was never inserted, so the trusted result is -1.
             */
            NumberAxis freshA = new NumberAxis(labelA);
            NumberAxis freshB = new NumberAxis(labelB);
            int freshIdxA = fuzzPlot.getRangeAxisIndex(freshA);
            int freshIdxB = fuzzPlot.getRangeAxisIndex(freshB);
            if (freshIdxA != -1) {
                fail("rangeaxis-distinct-instance-a", "fresh NumberAxis(labelA) expected=-1 actual=" + freshIdxA);
            }
            if (freshIdxB != -1) {
                fail("rangeaxis-distinct-instance-b", "fresh NumberAxis(labelB) expected=-1 actual=" + freshIdxB);
            }

            /*
             * Read-only post-condition:
             * getRangeAxisIndex is a query; repeating it on unchanged plot state must yield the same answer.
             * A patch that corrupts hidden ObjectList state during lookup would violate this without throwing.
             */
            int idxA2 = fuzzPlot.getRangeAxisIndex(axisA);
            int idxB2 = fuzzPlot.getRangeAxisIndex(axisB);
            if (idxA2 != idxA) {
                fail("rangeaxis-query-idempotent-a", "repeated getRangeAxisIndex(axisA) changed from " + idxA + " to " + idxA2);
            }
            if (idxB2 != idxB) {
                fail("rangeaxis-query-idempotent-b", "repeated getRangeAxisIndex(axisB) changed from " + idxB + " to " + idxB2);
            }
        } catch (RuntimeException e) {
            return;
        }
    }
}

