package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.optimization.OptimizationException;

public class FuzzHarness {
    private static void requireApprox(String oracleId, String what, double expected, double actual, double tol) {
        if (Math.abs(expected - actual) > tol) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + oracleId + "] semantic mismatch: " + what
                    + " expected=" + expected + " actual=" + actual + " tol=" + tol);
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        data.remainingBytes();

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();

        optimizer.rows = 3;
        optimizer.cols = 2;

        optimizer.residualsWeights = new double[] { 2.0d, 2.0d, 2.0d };

        /* Known-answer construction:
         * getChiSquare() is documented as summing the weighted residual contribution
         * over residuals/residualsWeights. We choose the state so the correct weighted
         * chi-square is exactly 0.01:
         *   2 * r^2 = 0.01  =>  r = sqrt(0.005)
         * The buggy code divides by weight instead, yielding 0.0025 instead of 0.01.
         */
        optimizer.residuals = new double[] { Math.sqrt(0.005d), 0.0d, 0.0d };

        /* Choose a full-rank jacobian whose covariance is approximately the values
         * asserted by testCircleFitting after adding perfect measurements.
         */
        optimizer.jacobian = new double[][] {
            { 25.0000005d, -0.005d },
            { 0.0d,        25.00000000000002d },
            { 0.0d,         0.0d }
        };

        double chi = optimizer.getChiSquare();

        /* Lifted/known oracle for the patched method itself:
         * with the state established above, the documented chi-square must be 0.01.
         * This is the exact behavioral difference in the patch.
         */
        requireApprox("chi-known-answer", "getChiSquare()", 0.01d, chi, 1.0e-15d);

        double[][] cov;
        double[] errors;
        try {
            cov = optimizer.getCovariances();
            errors = optimizer.guessParametersErrors();
        } catch (FunctionEvaluationException e) {
            throw new RuntimeException(e);
        } catch (OptimizationException e) {
            throw new RuntimeException(e);
        }

        requireApprox("lifted-cov-00", "cov[0][0]", 0.0016d, cov[0][0], 0.001d);
        requireApprox("lifted-cov-01", "cov[0][1]", 3.2e-7d, cov[0][1], 1.0e-9d);
        requireApprox("lifted-cov-sym", "cov[1][0] symmetry", cov[0][1], cov[1][0], 1.0e-14d);
        requireApprox("lifted-cov-11", "cov[1][1]", 0.0016d, cov[1][1], 0.001d);

        /* Lifted from testCircleFitting second phase:
         * errors[i] = sqrt(covar[i][i]) * sqrt(getChiSquare() / (rows - cols)).
         * With cov ~ 0.0016 and the known-answer chi-square 0.01, both errors are 0.004.
         * On the buggy build, getChiSquare() is too small by a factor of 4, so errors
         * are about half-sized (~0.002), matching the real regression shape.
         */
        requireApprox("lifted-err-0", "errors[0]", 0.004d, errors[0], 0.001d);
        requireApprox("lifted-err-1", "errors[1]", 0.004d, errors[1], 0.001d);
    }
}

