package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        int fuzzMode = data.consumeInt(0, 2);
        try {
            runLiftedCircleTest();
            if (fuzzMode != 0) {
                runTrustedMetamorphicVariant(data);
            }
        } catch (FuzzerSecurityIssueLow e) {
            throw e;
        } catch (RuntimeException e) {
            if (e.getMessage() != null && e.getMessage().startsWith("[oracle:")) {
                throw e;
            }
            return;
        } catch (Throwable t) {
            return;
        }
    }

    private static void runLiftedCircleTest() throws FunctionEvaluationException, OptimizationException {
        Circle circle = new Circle();
        circle.addPoint(30.0, 68.0);
        circle.addPoint(50.0, -6.0);
        circle.addPoint(110.0, -20.0);
        circle.addPoint(35.0, 15.0);
        circle.addPoint(45.0, 97.0);

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        VectorialPointValuePair optimum =
                optimizer.optimize(
                        circle,
                        new double[] {0, 0, 0, 0, 0},
                        new double[] {1, 1, 1, 1, 1},
                        new double[] {98.680, 47.345});

        assertTrue(
                "lifted-evaluations",
                optimizer.getEvaluations() < 10,
                "optimizer.getEvaluations() < 10 was false: " + optimizer.getEvaluations());
        assertTrue(
                "lifted-jacobian-evaluations",
                optimizer.getJacobianEvaluations() < 10,
                "optimizer.getJacobianEvaluations() < 10 was false: " + optimizer.getJacobianEvaluations());

        double rms = optimizer.getRMS();
        assertClose(
                "lifted-rms",
                1.768262623567235,
                Math.sqrt(circle.getN()) * rms,
                1.0e-10,
                "Math.sqrt(circle.getN()) * optimizer.getRMS()");
        Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);
        assertClose(
                "lifted-radius",
                69.96016176931406,
                circle.getRadius(center),
                1.0e-10,
                "circle.getRadius(center)");
        assertClose(
                "lifted-center-x",
                96.07590211815305,
                center.x,
                1.0e-10,
                "center.x");
        assertClose(
                "lifted-center-y",
                48.13516790438953,
                center.y,
                1.0e-10,
                "center.y");

        double[][] cov = optimizer.getCovariances();
        assertClose("lifted-cov00", 1.839, cov[0][0], 0.001, "cov[0][0]");
        assertClose("lifted-cov01", 0.731, cov[0][1], 0.001, "cov[0][1]");
        assertClose("lifted-cov-sym", cov[0][1], cov[1][0], 1.0e-14, "cov symmetry");
        assertClose("lifted-cov11", 0.786, cov[1][1], 0.001, "cov[1][1]");

        double[] errors = optimizer.guessParametersErrors();
        assertClose("lifted-errors0", 1.384, errors[0], 0.001, "errors[0]");
        assertClose("lifted-errors1", 0.905, errors[1], 0.001, "errors[1]");

        double r = circle.getRadius(center);
        for (double d = 0; d < 2 * Math.PI; d += 0.01) {
            circle.addPoint(center.x + r * Math.cos(d), center.y + r * Math.sin(d));
        }
        double[] target = new double[circle.getN()];
        Arrays.fill(target, 0.0);
        double[] weights = new double[circle.getN()];
        Arrays.fill(weights, 2.0);
        optimizer.optimize(circle, target, weights, new double[] {98.680, 47.345});

        cov = optimizer.getCovariances();
        assertClose("lifted-dense-cov00", 0.0016, cov[0][0], 0.001, "cov[0][0] after perfect measurements");
        assertClose("lifted-dense-cov01", 3.2e-7, cov[0][1], 1.0e-9, "cov[0][1] after perfect measurements");
        assertClose("lifted-dense-cov-sym", cov[0][1], cov[1][0], 1.0e-14, "cov symmetry after perfect measurements");
        assertClose("lifted-dense-cov11", 0.0016, cov[1][1], 0.001, "cov[1][1] after perfect measurements");

        errors = optimizer.guessParametersErrors();
        assertClose("lifted-dense-errors0", 0.004, errors[0], 0.001, "errors[0] after perfect measurements");
        assertClose("lifted-dense-errors1", 0.004, errors[1], 0.001, "errors[1] after perfect measurements");

        /* Contract-based cross-member check:
         * getRMS() docs say RMS is sqrt(c / n), where c is the minimized criterion.
         * getChiSquare() docs define the same weighted sum over the residuals/weights state.
         * updateResidualsAndCost() writes residuals, residualsWeights, rows that both readers consume.
         * Therefore, after optimize() established that shared state, every correct implementation must satisfy:
         * getChiSquare() == rows * getRMS()^2.
         * A "fix" that only suppresses/changes one reader's computation silently violates this post-condition.
         */
        double chiSquare = optimizer.getChiSquare();
        double expectedFromRms = circle.getN() * optimizer.getRMS() * optimizer.getRMS();
        assertClose(
                "rms-chi-square-consistency",
                expectedFromRms,
                chiSquare,
                1.0e-12,
                "getChiSquare() vs rows * getRMS()^2");
    }

    private static void runTrustedMetamorphicVariant(FuzzedDataProvider data)
            throws FunctionEvaluationException, OptimizationException {
        Circle circle = new Circle();
        circle.addPoint(30.0, 68.0);
        circle.addPoint(50.0, -6.0);
        circle.addPoint(110.0, -20.0);
        circle.addPoint(35.0, 15.0);
        circle.addPoint(45.0, 97.0);

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        VectorialPointValuePair optimum =
                optimizer.optimize(
                        circle,
                        new double[] {0, 0, 0, 0, 0},
                        new double[] {1, 1, 1, 1, 1},
                        new double[] {98.680, 47.345});

        Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);
        double r = circle.getRadius(center);

        int extraPoints = data.consumeInt(1, 80);
        int weightInt = data.consumeInt(1, 8);
        double weight = (double) weightInt;

        for (int i = 0; i < extraPoints; i++) {
            double angle = (2.0 * Math.PI * i) / extraPoints;
            circle.addPoint(center.x + r * Math.cos(angle), center.y + r * Math.sin(angle));
        }

        double[] target = new double[circle.getN()];
        Arrays.fill(target, 0.0);
        double[] weights = new double[circle.getN()];
        Arrays.fill(weights, weight);
        optimizer.optimize(circle, target, weights, new double[] {98.680, 47.345});

        /* Same documented guarantee as above; this generalizes to fuzzed positive uniform weights and
         * non-degenerate added perfect points because both readers consume exactly the same residual state. */
        double chiSquare = optimizer.getChiSquare();
        double expectedFromRms = circle.getN() * optimizer.getRMS() * optimizer.getRMS();
        assertClose(
                "fuzzed-rms-chi-square-consistency",
                expectedFromRms,
                chiSquare,
                1.0e-10,
                "getChiSquare() vs rows * getRMS()^2 on fuzzed positive-weight circle fit");
    }

    private static void assertTrue(String id, boolean condition, String detail) {
        if (!condition) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: " + detail);
        }
    }

    private static void assertClose(String id, double expected, double actual, double tol, String what) {
        boolean ok;
        if (Double.isNaN(expected)) {
            ok = Double.isNaN(actual);
        } else if (Double.isInfinite(expected) || Double.isInfinite(actual)) {
            ok = expected == actual;
        } else {
            ok = Math.abs(expected - actual) <= tol;
        }
        if (!ok) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:" + id + "] semantic mismatch: " + what
                            + " expected=" + expected
                            + " actual=" + actual
                            + " tol=" + tol);
        }
    }
}

class Circle implements DifferentiableMultivariateVectorialFunction {
    private final ArrayList<Point2D.Double> points = new ArrayList<Point2D.Double>();

    public void addPoint(double px, double py) {
        points.add(new Point2D.Double(px, py));
    }

    public int getN() {
        return points.size();
    }

    public double getRadius(Point2D.Double center) {
        double r = 0.0;
        for (Point2D.Double p : points) {
            r += p.distance(center);
        }
        return r / points.size();
    }

    public double[] value(double[] variables) throws FunctionEvaluationException {
        Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
        double radius = getRadius(center);
        double[] residuals = new double[points.size()];
        for (int i = 0; i < residuals.length; i++) {
            residuals[i] = points.get(i).distance(center) - radius;
        }
        return residuals;
    }

    public MultivariateMatrixFunction jacobian() {
        return new MultivariateMatrixFunction() {
            public double[][] value(double[] variables) throws FunctionEvaluationException {
                Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
                int n = points.size();
                double[][] jacobian = new double[n][2];
                List<Double> dRdX = new ArrayList<Double>(n);
                List<Double> dRdY = new ArrayList<Double>(n);
                double sx = 0.0;
                double sy = 0.0;

                for (Point2D.Double p : points) {
                    double dx = center.x - p.x;
                    double dy = center.y - p.y;
                    double di = Math.sqrt(dx * dx + dy * dy);
                    double drdx;
                    double drdy;
                    if (di == 0.0) {
                        drdx = 0.0;
                        drdy = 0.0;
                    } else {
                        drdx = dx / di;
                        drdy = dy / di;
                    }
                    dRdX.add(Double.valueOf(drdx));
                    dRdY.add(Double.valueOf(drdy));
                    sx += drdx;
                    sy += drdy;
                }

                double meanX = sx / n;
                double meanY = sy / n;
                for (int i = 0; i < n; i++) {
                    jacobian[i][0] = dRdX.get(i).doubleValue() - meanX;
                    jacobian[i][1] = dRdY.get(i).doubleValue() - meanY;
                }

                return jacobian;
            }
        };
    }
}
